import * as THREE from './vendor/three.module.js';
import {VOLT_STORM as C} from './runner-storm.js?v=ball-lightning-265';
export class RunnerStormFX {
 constructor(scene,camera){this.camera=camera;this.root=new THREE.Group();scene.add(this.root);const mat=(color,opacity=1)=>new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:false,toneMapped:false,side:THREE.DoubleSide});this.core=new THREE.Mesh(new THREE.IcosahedronGeometry(1,2),mat('#d5ffff',.8));this.halo=new THREE.Mesh(this.core.geometry,mat('#368dff',.15));this.shell=new THREE.Mesh(new THREE.IcosahedronGeometry(1,1),new THREE.MeshBasicMaterial({color:'#83caff',wireframe:true,transparent:true,opacity:.5,toneMapped:false}));this.marker=new THREE.Mesh(new THREE.RingGeometry(.9,1,64),mat('#7fedff',.8));this.marker.rotation.x=-Math.PI/2;this.shock=new THREE.Mesh(new THREE.SphereGeometry(1,24,12),mat('#adfaff',.2));this.lines=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5,1,true),mat('#c9ffff'),256);this.lines.frustumCulled=false;this.bar=new THREE.Group();this.back=new THREE.Mesh(new THREE.PlaneGeometry(2.9,.27),mat('#061322'));this.fill=new THREE.Mesh(new THREE.PlaneGeometry(2.6,.15),mat('#67edff'));this.fill.position.z=.012;this.bar.add(this.back,this.fill);this.root.add(this.core,this.halo,this.shell,this.marker,this.shock,this.lines,this.bar);this.plasma=new THREE.Mesh(new THREE.SphereGeometry(1,32,20),new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{time:{value:0},energy:{value:1},flash:{value:0}},vertexShader:`varying vec3 vN;varying vec3 vView;varying vec3 vP;void main(){vP=position;vec4 mv=modelViewMatrix*vec4(position,1.);vView=-mv.xyz;vN=normalize(normalMatrix*normal);gl_Position=projectionMatrix*mv;}`,fragmentShader:`uniform float time;uniform float energy;uniform float flash;varying vec3 vN;varying vec3 vView;varying vec3 vP;void main(){float rim=pow(1.-abs(dot(normalize(vN),normalize(vView))),2.2);float ribbons=pow(.5+.5*sin(vP.y*19.+sin(vP.x*11.+time*2.)*2.+vP.z*7.-time*5.),9.);float cells=pow(.5+.5*sin(vP.x*17.+vP.z*13.+sin(vP.y*9.-time*3.)),15.);vec3 color=mix(vec3(.04,.22,.95),vec3(.3,.9,1.),rim);color=mix(color,vec3(.85,1.,1.),min(1.,ribbons+cells+flash));gl_FragColor=vec4(color,(.08+rim*.6+ribbons*.34+cells*.17)*(.7+energy*.3));}`}));this.orbits=Array.from({length:3},()=>new THREE.Mesh(new THREE.TorusGeometry(1,.014,5,64),new THREE.MeshBasicMaterial({color:'#97f5ff',transparent:true,opacity:.7,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false})));this.orbSparks=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,4),mat('#b9faff'),36);this.orbSparks.frustumCulled=false;this.zapFlashes=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,1),mat('#dfffff',.8),24);this.zapFlashes.frustumCulled=false;this.root.add(this.plasma,...this.orbits,this.orbSparks,this.zapFlashes);this.back.scale.x=4.2/2.9;this.fill.scale.x=3.8/2.6;this.dummy=new THREE.Object3D();this.sky=new SkyStrikeFX(this.root);this.clear();}
 clear(){this.hide();this.sky.clear();}
 hide(){for(const m of[this.core,this.halo,this.shell,this.marker,this.shock,this.bar,this.plasma,...this.orbits])m.visible=false;this.orbSparks.count=this.zapFlashes.count=0;this.lines.count=0;}
 update(dt,time,storm){const casting=storm.cast,progress=casting?1-casting.remaining/C.orbCastSeconds:1,o=casting?{position:casting.from.clone().addScaledVector(casting.direction,.6),energy:C.orbEnergy,flash:0}:storm.orb,s=storm.strike;this.hide();this.sky.update(dt,time,storm);const segments=[],arc=(a,b,width,seed)=>{let last=a.clone();for(let i=1;i<=12;i++){const f=i/12,p=a.clone().lerp(b,f);if(i<12)p.add(new THREE.Vector3(Math.sin(i*7+time*40+seed),Math.sin(i*9+time*34),Math.cos(i*5-time*31+seed)).multiplyScalar(width>.15?.8:.18));segments.push({a:last,b:p,width});last=p;}};
  if(o){for(const m of[this.core,this.halo,this.shell]){m.visible=true;m.position.copy(o.position);}const pulse=(1+Math.sin(time*9)*.04)*(casting?.15+.55*progress:1);this.core.scale.setScalar(C.orbRadius*.48*pulse);this.core.material.opacity=.65;this.halo.scale.setScalar(C.orbRadius*1.12*pulse);this.halo.material.opacity=.07;this.shell.scale.setScalar(C.orbRadius*1.01*(casting?.15+.85*progress:1));this.shell.material.opacity=.12;this.plasma.visible=true;this.plasma.position.copy(o.position);this.plasma.scale.setScalar(C.orbRadius*pulse);this.plasma.material.uniforms.time.value=time;this.plasma.material.uniforms.energy.value=o.energy/C.orbEnergy;this.plasma.material.uniforms.flash.value=o.flash;for(let i=0;i<3;i++){const m=this.orbits[i];m.visible=true;m.position.copy(o.position);m.scale.setScalar(C.orbRadius*(1.06+i*.035)*(casting?.15+.85*progress:1));m.rotation.set(time*(.5+i*.15)+i*Math.PI/3,time*(.3+i*.1),time*.2+i);m.material.opacity=o.flash>0?1:.55;}this.orbSparks.count=36;for(let i=0;i<36;i++){const a=i*2.39996+time*.7,b=Math.sin(i*1.7+time*.3),r=C.orbRadius*(1.08+(time*.6+i/36)%1*.35)*(casting?.15+.85*progress:1),v=new THREE.Vector3(Math.cos(a)*Math.sqrt(1-b*b),b,Math.sin(a)*Math.sqrt(1-b*b)),p=o.position.clone().addScaledVector(v,r);this.dummy.position.copy(p);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),v);this.dummy.scale.set(.02,.08+.18*((i/36+time*.6)%1),.02);this.dummy.updateMatrix();this.orbSparks.setMatrixAt(i,this.dummy.matrix);}this.orbSparks.instanceMatrix.needsUpdate=true;this.shell.rotation.set(time*.4,time*.7,0);this.core.material.color.set(o.flash>0?'#ffffff':'#a9eaff');for(let i=0;i<6;i++){const a=time*1.5+i*Math.PI/3,p=o.position.clone().add(new THREE.Vector3(Math.cos(a),Math.sin(a*1.4),Math.sin(a)).multiplyScalar(C.orbRadius*(casting?.15+.85*progress:1)));arc(o.position,p,.04,i);}this.bar.visible=!casting;this.bar.position.copy(o.position).add(new THREE.Vector3(0,C.orbRadius+1,0));this.bar.quaternion.copy(this.camera.quaternion);const q=o.energy/C.orbEnergy;this.fill.scale.x=q*3.8/2.6;this.fill.position.x=-1.9*(1-q);this.fill.material.color.set(o.flash>0?'#ffffff':q<.2?'#ffb663':'#67edff');}
  if(s){this.marker.visible=true;this.marker.position.copy(s.point).y+=.08;const p=1-s.remaining/C.strikeDelay;this.marker.scale.setScalar(C.strikeRadius);this.marker.material.color.set(p>.8?'#edfbff':'#60d9ff');this.marker.material.opacity=.5+p*.5;}
  for(const e of storm.events){if(e.kind==='fade'){this.shock.visible=true;this.shock.position.copy(e.point);this.shock.scale.setScalar(C.orbRadius*(1+e.age*4));this.shock.material.opacity=.18*Math.max(0,1-e.age/.25);continue;}if(e.kind==='zap'){arc(e.from,e.point,.065*(1-e.age/.25),7);if(this.zapFlashes.count<24){this.dummy.position.copy(e.point);this.dummy.quaternion.identity();this.dummy.scale.setScalar(.45*(1-e.age/.25));this.dummy.updateMatrix();this.zapFlashes.setMatrixAt(this.zapFlashes.count++,this.dummy.matrix);}continue;}}

  let n=0;for(const p of segments){if(n>=256)break;const d=p.b.clone().sub(p.a);this.dummy.position.copy(p.a).lerp(p.b,.5);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());this.dummy.scale.set(Math.max(.001,p.width),d.length(),Math.max(.001,p.width));this.dummy.updateMatrix();this.lines.setMatrixAt(n++,this.dummy.matrix);}this.lines.count=n;this.lines.instanceMatrix.needsUpdate=true;this.zapFlashes.instanceMatrix.needsUpdate=true;
 }
 diagnostics(){return{plasma:this.plasma.visible,orbitRings:this.orbits.filter(m=>m.visible).length,orbSparks:this.orbSparks.count,zapImpacts:this.zapFlashes.count,sky:this.sky.diagnostics(),orbVisible:this.core.visible,barVisible:this.bar.visible,marker:this.marker.visible,segments:this.lines.count,limit:256};}
}
